item.aggregated_output:
{
  "type": "object",
  "candidateOwnedPaths": true,
  "required": ["run", "task", "phases"],
  "properties": {
    "run": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
    "task": {"type": "string"},
    "phases": {
      "type": "array", "minItems": 1, "uniqueBy": "id",
      "items": {
        "type": "object",
        "required": ["id", "workers"],
        "properties": {
          "id": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
          "barrier": {"type": "boolean"},
          "loop": {
            "type": "object", "required": ["review", "fix", "max_rounds"],
            "properties": {
              "review": {"type": "string", "const": "reviewer"},
              "fix": {"type": "string", "const": "fixer"},
              "max_rounds": {"type": "integer", "minimum": 1}
            }
          },
          "workers": {
            "type": "array", "minItems": 1, "uniqueBy": "id",
            "disjointNormalizedPathsBy": "owns",
            "noConcurrentInputDependencies": true,
            "items": {
              "type": "object",
              "required": ["id", "role", "goal", "inputs", "owns"],
              "allOf": [
                {
                  "if": {"properties": {"role": {"enum": ["reviewer", "verifier", "judge"]}}},
                  "then": {"forbiddenProperties": ["verify"], "properties": {"owns": {"const": []}}}
                },
                {
                  "if": {"properties": {"role": {"enum": ["writer", "implementer", "fixer"]}}},
                  "then": {"required": ["verify"]}
                },
                {
                  "if": {"properties": {"role": {"const": "verifier"}}},
                  "then": {"required": ["candidates"]}
                }
              ],
              "properties": {
                "id": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
                "role": {
                  "type": "string",
                  "enum": ["writer", "implementer", "reviewer", "verifier", "fixer", "judge"]
                },
                "goal": {"type": "string", "pattern": "\\S"},
                "inputs": {"type": "array", "items": {"type": "string"}},
                "owns": {"type": "array", "items": {"type": "string", "repoRelativePath": true, "notRepoPathPrefix": ".work-team"}},
                "verify": {"type": "string", "pattern": "\\S"},
                "candidates": {
                  "type": "array", "minItems": 1, "uniqueBy": "id",
                  "items": {
                    "type": "object", "required": ["id", "owner", "path", "issue"],
                    "properties": {
                      "id": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]*\\Z"},
                      "owner": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
                      "path": {"type": "string", "repoRelativePath": true, "notRepoPathPrefix": ".work-team"},
                      "issue": {"type": "string", "pattern": "\\S"}
                    }
                  }
                },
                "group": {"type": "string"},
                "model": {"type": "string"}
              }
            }
          }
        }
      }
    }
  }
}

--- review schema ---
{
  "type": "object",
  "forbiddenProperties": ["verify_output"],
  "required": ["verdict", "findings"],
  "allOf": [
    {
      "if": {"properties": {"verdict": {"const": "changes_required"}}},
      "then": {
        "properties": {
          "findings": {
            "minItems": 1,
            "contains": {"properties": {"scope": {"const": "spec"}}}
          }
        }
      }
    },
    {
      "if": {"properties": {"verdict": {"const": "pass"}}},
      "then": {
        "properties": {
          "findings": {
            "items": {"properties": {"scope": {"const": "adjacent"}}}
          }
        }
      }
    }
  ],
  "properties": {
    "verdict": {"type": "string", "enum": ["pass", "changes_required"]},
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["severity", "scope", "where", "owner", "path", "issue", "fix"],
        "properties": {
          "severity": {"type": "string", "enum": ["blocker", "important", "minor"]},
          "scope": {"type": "string", "enum": ["spec", "adjacent"]},
          "where": {"type": "string", "minLength": 1, "pattern": "\\S"},
          "owner": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
          "path": {"type": "string", "repoRelativePath": true, "notRepoPathPrefix": ".work-team"},
          "issue": {"type": "string", "minLength": 1, "pattern": "\\S"},
          "fix": {"type": "string", "minLength": 1, "pattern": "\\S"},
          "evidence": {"type": "string"}
        }
      }
    }
  }
}

--- verifier schema ---
{
  "type": "object",
  "forbiddenProperties": ["verify_output"],
  "required": ["candidates"],
  "properties": {
    "candidates": {
      "type": "array",
      "minItems": 1,
      "uniqueBy": "id",
      "items": {
        "type": "object",
        "required": ["id", "verdict", "evidence"],
        "properties": {
          "id": {"type": "string", "minLength": 1},
          "verdict": {"type": "string", "enum": ["confirmed", "refuted"]},
          "evidence": {"type": "string", "minLength": 1, "pattern": "\\S"}
        }
      }
    }
  }
}

--- result schema ---
{
  "type": "object",
  "runArtifactPaths": true,
  "required": ["run", "outcome", "verification", "residual", "workers", "plan", "log"],
  "allOf": [
    {
      "if": {"properties": {"outcome": {"const": "complete"}}},
      "then": {
        "properties": {
          "verification": {
            "minItems": 1,
            "items": {"properties": {"passed": {"const": true}}}
          },
          "residual": {
            "items": {
              "properties": {
                "kind": {"const": "finding"}
              },
              "allOf": [
                {
                  "if": {"properties": {"kind": {"enum": ["finding", "loop_cap"]}}},
                  "then": {"properties": {"severity": {"enum": ["minor"]}}}
                }
              ]
            }
          },
          "workers": {
            "minItems": 1,
            "items": {"properties": {"status": {"enum": ["ok", "retried"]}}}
          }
        }
      }
    }
  ],
  "properties": {
    "run": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*\\Z"},
    "outcome": {"type": "string", "enum": ["complete", "partial", "stopped"]},
    "verification": {
      "type": "array",
      "items": {
        "type": "object", "required": ["command", "passed", "output"],
        "properties": {"command": {"type": "string", "pattern": "\\S"}, "passed": {"type": "boolean"}, "output": {"type": "string"}, "summary": {"type": "string"}}
      }
    },
    "residual": {
      "type": "array",
      "items": {
        "type": "object", "required": ["kind", "detail"],
        "allOf": [
          {
            "if": {"properties": {"kind": {"enum": ["finding", "loop_cap"]}}},
            "then": {"required": ["severity", "scope"]}
          }
        ],
        "properties": {
          "kind": {"type": "string", "enum": ["finding", "gap", "worker_failed", "loop_cap", "invalid_return", "skipped"]},
          "detail": {"type": "string"},
          "severity": {"type": "string", "enum": ["blocker", "important", "minor"]},
          "scope": {"type": "string", "enum": ["spec", "adjacent"]},
          "source": {"type": "string"}
        }
      }
    },
    "workers": {
      "type": "array",
      "items": {
        "type": "object", "required": ["id", "role", "status"],
        "properties": {
          "id": {"type": "string"}, "role": {"type": "string"},
          "status": {"type": "string", "enum": ["ok", "failed", "retried", "invalid"]},
          "summary": {"type": "string"}
        }
      }
    },
    "plan": {"type": "string"},
    "log": {"type": "string"}
  }
}

